    public function getRegStatusBadgeAttribute()
    {
        return RegStatus::badge($this->registration_status);
    }

    public function getFileStatusBadgeAttribute()
    {
        return FileStatus::badge($this->file_status);
    }

    public function getNamaPemohonAttribute()
    {
        if(in_array($this->file_status, [15, 20])) {
            $pemohon = LendingFile::with('owner')->where('file_id', $this->id)->whereNotIn('status', [50, 60])->latest()->first();
            if($pemohon) return $pemohon->owner->name;
            else return '-';
        } else {
            return '-';
        }
    }

    public function getFileActiveAttribute()
    {
        if($this->active == 1) {
            return '<div class="rounded small fw-medium shadow-sm p-1 text-center" style="color: white; background-color: rgb(54, 162, 235);">AKTIF</div>';
        } else {
            return '<div class="rounded small fw-medium shadow-sm p-1 text-center" style="color: white; background-color: rgb(255, 99, 132);">TIDAK AKTIF</div>';
        }
    }

    public function getLatestDocNumActivityAttribute()
    {
        if ($this->document_number) {
            $latestDocNumActivity = DocumentNumberHistory::select('activity')
                                        ->where('file_id', '=', $this->id)
                                        ->where('value', '=', $this->document_number)
                                        ->latest()
                                        ->first();

            if ($latestDocNumActivity) return $latestDocNumActivity->activity;
            else return null;
        } else return null;
    }

    public function scopeCompleteRegistration($query)
    {
        return $query->where('registration_status', RegStatus::SELESAI);
    }

    public function scopeOrderByIscafNo($query, $direction = 'asc')
    {
        return $query->orderBy(
            FileInfo::select('iscaf_no')
                ->whereColumn('file_information.app_id', 'apps.id')
                ->orderBy('iscaf_no', $direction)
                ->limit(1),
            $direction
        );
    }

    /**
     * Model Relationship start here
     *
     **/
    public function documents()
    {
        return $this->morphMany(Document::class, 'document')->latest();
    }

    public function app()
    {
        return $this->hasOne(App::class, 'id', 'app_id');
    }

    public function group()
    {
        return $this->belongsTo(Group::class, 'group_id', 'id');

    }

    public function historyDocumentNumber()
    {
        return $this->hasMany(DocumentNumberHistory::class, 'file_id', 'id');
    }

    public function fileHistory()
    {
        return $this->hasMany(FileHistory::class, 'file_id', 'id')->latest();
    }

    public function hasLending()
    {
        return $this->hasMany(LendingFile::class, 'file_id', 'id');
    }
